import{c as t,Q as r,j as o,m as a}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"Claude Opus 4.5 System Card","description":"","frontmatter":{"url":"https://www.anthropic.com/claude-opus-4-5-system-card","title":"Claude Opus 4.5 System Card","archived_date":"2026-06-24T00:00:00.000Z","authors":["Anthropic"],"domains":["system-card"],"published_date":"2025-11-01T00:00:00.000Z","source_url":"https://www.anthropic.com/claude-opus-4-5-system-card","web_only":true},"headers":[],"relativePath":"research/papers/2025-11-01-claude-opus-4-5-system-card.md","filePath":"research/papers/2025-11-01-claude-opus-4-5-system-card.md","lastUpdated":1785909234000}'),s={name:"research/papers/2025-11-01-claude-opus-4-5-system-card.md"};function n(l,e,i,d,c,u){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="claude-opus-4-5-system-card" tabindex="-1">Claude Opus 4.5 System Card <a class="header-anchor" href="#claude-opus-4-5-system-card" aria-label="Permalink to &quot;Claude Opus 4.5 System Card&quot;">​</a></h1><p><strong>Source</strong>: Anthropic 官方 system card（web-only，無 arXiv PDF）— <a href="https://www.anthropic.com/claude-opus-4-5-system-card" target="_blank" rel="noreferrer">https://www.anthropic.com/claude-opus-4-5-system-card</a> （原始 URL 307 重導向至官方 PDF <code>www-cdn.anthropic.com/.../Claude%20Opus%204.5%20System%20Card.pdf</code>，內容相同。） <strong>Published</strong>: November 2025（清單記 2025-11-01；模型公開發布日為 2025-11-24）</p><blockquote><p>依官方公開資訊整理；數字以可交叉驗證者為主，不確定處保守描述。</p></blockquote><hr><h2 id="摘要-依官網內容整理" tabindex="-1">摘要（依官網內容整理） <a class="header-anchor" href="#摘要-依官網內容整理" aria-label="Permalink to &quot;摘要（依官網內容整理）&quot;">​</a></h2><p>Opus 4.5 為當時「全球最佳 coding / agents / computer use 模型」，並伴隨大幅降價（Opus 系列由 $15/$75 降至 $5/$25）。effort level 調控的 token 效率為核心賣點。</p><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="模型與定位" tabindex="-1">模型與定位 <a class="header-anchor" href="#模型與定位" aria-label="Permalink to &quot;模型與定位&quot;">​</a></h3><ul><li><strong>Claude Opus 4.5</strong>：4.5 世代旗艦；coding/agent/computer-use SOTA，超越同期 GPT-5.1、Gemini 3 Pro（依官方陳述）。</li></ul><h3 id="關鍵能力-安全評估數字-依官方公開資訊整理" tabindex="-1">關鍵能力 / 安全評估數字（依官方公開資訊整理） <a class="header-anchor" href="#關鍵能力-安全評估數字-依官方公開資訊整理" aria-label="Permalink to &quot;關鍵能力 / 安全評估數字（依官方公開資訊整理）&quot;">​</a></h3><ul><li><strong>SWE-bench Verified</strong>：<strong>80.9%</strong>。</li><li><strong>Effort 效率</strong>：medium effort 即可追平 Sonnet 4.5 最佳 SWE-bench 分數，且少用 <strong>76%</strong> output tokens；最高 effort 超越 Sonnet 4.5 達 <strong>4.3pp</strong>，且少用 <strong>48%</strong> tokens。</li><li><strong>Pricing</strong>：<strong>$5 / 1M input、$25 / 1M output</strong>（較前代 Opus 大幅下降）。</li><li><strong>AI Safety Level</strong>：<strong>ASL-3</strong>；官方稱已大致達到「straightforward ASL-4 rule-out」基準閾值（即接近但以基準任務排除 ASL-4）。</li></ul><h3 id="值得注意章節" tabindex="-1">值得注意章節 <a class="header-anchor" href="#值得注意章節" aria-label="Permalink to &quot;值得注意章節&quot;">​</a></h3><ul><li>effort-first 的量化證據：同分數下 effort 調控可省下 48–76% output tokens——直接的成本/品質帕累托。</li></ul><hr><h2 id="workspace-關聯-評估" tabindex="-1">Workspace 關聯（評估） <a class="header-anchor" href="#workspace-關聯-評估" aria-label="Permalink to &quot;Workspace 關聯（評估）&quot;">​</a></h2><ul><li><strong>effort-first 鐵證</strong>：CLAUDE.md「Effort 先於 model；high 為甜蜜點，xhigh 留給溢出任務」在此卡有量化背書——同分數省 76% tokens 正是「先調 effort」的價值。</li><li><strong><code>pilot</code>（tier=ceiling，原 <code>opus-pilot</code>） ceiling 更新</strong>：80.9% SWE-bench 與大幅降價，使 Opus 檔位的成本門檻下降，<code>pilot</code>（tier=ceiling，原 <code>opus-pilot</code>）的使用時機可放寬。</li><li><strong>model-selection-grid 校準</strong>：Opus 4.5 medium ≈ Sonnet 4.5 best，提示「跨檔位等效點」——選 model 前先確認 effort 是否已足。 〔v5.1：所引 workspace 細則已退役 → 見 <code>INDEX.md</code> §v5.1 規則退役對照〕</li></ul>',17)])])}const m=t(s,[["render",n]]);export{h as __pageData,m as default};
